#pragma STDC FP_CONTRACT OFF

#include <stdio.h>

static void viv_show_num(const char* label, double v) {
    if (label[0]) printf("%s: ", label);
    printf("%g\n", v + 0.0);
}

double i;
double total;

double sq(double x) {
    return (x * x);
}

int main(void) {
    total = 0.0;
    for (i = 0.0; i < 10.0; i = (i + 1.0)) {
        total = (total + sq(i));
    }
    viv_show_num("total", total);
    return 0;
}

